  ('ui.dashboard_scope', 'Dashboard Scope', 'Ownership scope of a dashboard: personal, shared, system. personal = owner only. shared = all tenant users. system = platform-seeded. Platform-governed ??? not tenant-extensible.', 'master', false, '{}'::jsonb, 'active', '00000000-0000-0000-0000-000000000000'::uuid),
  ('ui.density', 'UI Density', 'Information density preference: compact, comfortable, spacious. Controls row height, whitespace, and icon size across all grids/lists. Maps to master.principal_ui_profile.density_code. Tenant-extensible ??? tenants may add custom density levels.', 'master', true, '{}'::jsonb, 'active', '00000000-0000-0000-0000-000000000000'::uuid),
  ('ui.preference_code', 'UI Preference Code', 'Registry of allowed preference keys for master.principal_ui_preference. Prevents uncatalogued key proliferation. Tenant-extensible ??? tenants may register module-specific preference keys.', 'master', true, '{}'::jsonb, 'active', '00000000-0000-0000-0000-000000000000'::uuid),
  ('ui.surface_code', 'UI Surface Code', 'Registry of named UI surfaces (screens/panels) that preferences and views target. e.g. proc.po_list, ap.invoice_detail. Tenant-extensible ??? new surfaces added as modules ship.', 'master', true, '{}'::jsonb, 'active', '00000000-0000-0000-0000-000000000000'::uuid),
  ('ui.view_scope', 'Saved View Scope', 'Ownership scope of a saved view: personal, shared, system. personal = owner only. shared = all tenant users. system = platform-seeded. Platform-governed ??? not tenant-extensible.', 'master', false, '{}'::jsonb, 'active', '00000000-0000-0000-0000-000000000000'::uuid),
  ('ui.widget_type', 'Dashboard Widget Type', 'Classification of widget rendering type: chart, kpi_card, table, list, calendar, activity_feed, custom. Drives front-end component routing. Tenant-extensible ??? tenants may register custom widget types.', 'master', true, '{}'::jsonb, 'active', '00000000-0000-0000-0000-000000000000'::uuid)
